// This file is partially generated by AI.

//! 快照打包

use std::{
    collections::HashSet,
    fs, io,
    path::{Path, PathBuf},
};

use walkdir::WalkDir;
use webgal_language_core::{
    resource::{Config, FigureKind, Live2dModel, RESOURCE_ROOTS, ResourceKind, WmdlModel},
    sentence::{Sentence, SentenceExt},
};
use zip::{ZipWriter, write::SimpleFileOptions};

use crate::{Error, ErrorKind, PackConfig, ProgressReporter};

// -------- 结果 --------

/// 快照打包结果
#[derive(Debug, Default)]
pub struct PackResult {
    /// 已打包文件总数
    pub count: usize,
    /// 已打包文件总体积
    pub total_size: u64,
    /// 压缩包总体积
    pub final_size: u64,
    /// 扫描和打包过程遇到的错误
    pub errors: Vec<Error>,
    /// 是否被终止 (压缩包未完整生成)
    pub aborted: bool,
}

// -------- 打包器 --------

/// 快照打包器
pub struct Packer {
    pub(crate) source: PathBuf,
    pub(crate) destination: PathBuf,
    pub(crate) config: PackConfig,
    pub(crate) progress_reporter: Option<Box<dyn ProgressReporter>>,
}

/// 扫描与打包过程的共享状态
#[derive(Debug, Default)]
struct ScanState {
    /// 已收集的文件 (绝对路径)
    files: HashSet<PathBuf>,
    /// 已收集的场景 (项目相对路径, 用于递归去重)
    scenes: HashSet<PathBuf>,
    /// 已收集的立绘模型 (相对于 `game/figure/` 的路径, 用于递归去重)
    figures: HashSet<String>,
    /// 已收集文件累计体积
    cumulative_size: u64,
    /// 收集过程遇到的错误
    errors: Vec<Error>,
    /// 是否被汇报器要求终止
    terminated: bool,
}

impl Packer {
    /// 执行快照打包
    ///
    /// # Behavior
    /// * 扫描与打包过程中遇到的错误会记录到结果中, 默认继续执行.
    /// * 除 `game/` 下的资源目录 (`animation`, `background`, `bgm`, `figure`,
    ///   `scene`, `video`, `vocal`) 与配置文件 `config.txt` 外的文件, 将全部打包.
    /// * 进入初始场景 `start.txt`, 收集语句中出现的资源 (递归进入被调用场景).
    /// * 对于 Live2D 和 WMDL 立绘, 将打包立绘配置中关联的资源.
    /// * 不支持 Spine 等其他类型的立绘 (会报错).
    pub fn run(&self) -> PackResult {
        let mut state = ScanState::default();

        self.scan(&mut state);
        if state.terminated {
            return PackResult {
                errors: state.errors,
                aborted: true,
                ..Default::default()
            };
        }

        let (count, total_size, final_size) = self.pack(&mut state);
        PackResult {
            count,
            total_size,
            final_size,
            errors: state.errors,
            aborted: state.terminated,
        }
    }

    // -------- 扫描 --------

    /// 执行扫描, 收集需要打包的文件
    fn scan(&self, state: &mut ScanState) {
        if let Some(reporter) = &self.progress_reporter {
            reporter.on_scan_start();
        }

        // 1. 全量打包除游戏资源外的所有文件
        self.scan_common(state);
        if state.terminated {
            return;
        }

        // 2. 打包配置文件, 并收集其中引用的资源
        self.scan_config(state);
        if state.terminated {
            return;
        }

        // 3. 动画索引表始终打包 (引擎需要)
        let animation_table = self
            .source
            .join("game")
            .join("animation")
            .join("animationTable.json");
        if animation_table.is_file() {
            self.add_file(state, animation_table);
        }
        if state.terminated {
            return;
        }

        // 4. 从初始场景出发, 递归收集被调用的场景与资源
        self.scan_scenes(state);
        if state.terminated {
            return;
        }

        if let Some(reporter) = &self.progress_reporter {
            reporter.on_scan_complete(state.files.len(), state.cumulative_size);
        }
    }

    /// 全量扫描除游戏资源外的所有文件
    ///
    /// # Behavior
    /// * 跳过 `game/` 下的资源目录 (`animation`, `background`, `bgm`, `figure`,
    ///   `scene`, `video`, `vocal`) 与配置文件 `config.txt`,
    ///   这些文件由 [`Self::scan_config`] 与 [`Self::scan_scenes`] 按引用收集.
    fn scan_common(&self, state: &mut ScanState) {
        let source = self.source.clone();
        let walker = WalkDir::new(&source)
            .follow_links(self.config.follow_symlinks)
            .into_iter()
            .filter_entry(|entry| !Self::is_trimmed_resource(&source, entry));

        for result in walker {
            // 目录遍历失败
            let entry = match result {
                Ok(entry) => entry,
                Err(error) => {
                    self.push_scan_error(state, error.into());
                    if state.terminated {
                        return;
                    }
                    continue;
                }
            };

            // 仅收集文件
            if !entry.file_type().is_file() {
                continue;
            }

            self.add_file(state, entry.into_path());
            if state.terminated {
                return;
            }
        }
    }

    /// 判断条目是否属于需要按引用收集的游戏资源
    fn is_trimmed_resource(source: &Path, entry: &walkdir::DirEntry) -> bool {
        // 依据条目在项目中的相对路径判断
        let relative = entry.path().strip_prefix(source).unwrap_or(entry.path());
        if entry.file_type().is_dir() {
            // 资源目录整体跳过 (不进入遍历)
            RESOURCE_ROOTS
                .iter()
                .any(|root| relative == Path::new("game").join(root))
        } else {
            // 配置文件单独跳过
            relative == Path::new("game").join("config.txt")
        }
    }

    /// 扫描游戏配置
    ///
    /// # Behavior
    /// * 打包 `game/config.txt` 本身.
    /// * 收集配置中引用的资源: `Title_img` 与 `Game_Logo` 为背景图, `Title_bgm` 为背景音乐.
    fn scan_config(&self, state: &mut ScanState) {
        let config_path = self.source.join("game").join("config.txt");
        let content = match fs::read_to_string(&config_path) {
            Ok(content) => content,
            Err(error) if error.kind() == io::ErrorKind::NotFound => {
                self.push_scan_error(state, Error::new(config_path, ErrorKind::MissingResource));
                return;
            }
            Err(error) => {
                self.push_scan_error(state, Error::new(config_path, ErrorKind::Read(error)));
                return;
            }
        };

        // 打包配置文件本身
        self.add_file(state, config_path);

        // 收集配置引用的资源
        let config = Config::from_str(&content);
        for key in CONFIG_BACKGROUND_KEYS {
            self.scan_config_resource(state, &config, key, ResourceKind::Background);
        }
        for key in CONFIG_BGM_KEYS {
            self.scan_config_resource(state, &config, key, ResourceKind::Bgm);
        }
    }

    /// 收集配置条目引用的资源
    fn scan_config_resource(
        &self,
        state: &mut ScanState,
        config: &Config,
        key: &str,
        kind: ResourceKind,
    ) {
        let Some(value) = config.get_config(key).map(|(_, item)| item.value.trim()) else {
            return;
        };
        if value.is_empty() {
            return;
        }
        let path = self.source.join("game").join(kind.to_string()).join(value);
        self.add_file(state, path);
    }

    /// 扫描场景引用图
    fn scan_scenes(&self, state: &mut ScanState) {
        // 从初始场景开始递归扫描
        self.scan_scene(state, PathBuf::from("game/scene/start.txt"));
    }

    /// 扫描单个场景及其引用的资源
    fn scan_scene(&self, state: &mut ScanState, relative: PathBuf) {
        // 场景去重, 防止场景互相调用形成循环
        if !state.scenes.insert(relative.clone()) || state.terminated {
            return;
        }

        let path = self.source.join(&relative);
        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(error) if error.kind() == io::ErrorKind::NotFound => {
                self.push_scan_error(state, Error::new(path, ErrorKind::MissingResource));
                return;
            }
            Err(error) => {
                self.push_scan_error(state, Error::new(path, ErrorKind::Read(error)));
                return;
            }
        };
        self.add_file(state, path);

        // 逐行解析语句并收集资源
        for (line, content) in content.lines().enumerate() {
            let output = Sentence::from_str(content);

            // 记录解析错误 (解析失败仍继续收集已识别的资源)
            for error in output.errors {
                let error = Error::with_line(self.source.join(&relative), line + 1, error.into());
                self.push_scan_error(state, error);
                if state.terminated {
                    return;
                }
            }

            // 收集语句引用的资源
            for (kind, resource) in output.sentence.resources() {
                self.scan_resource(state, kind, &resource);
                if state.terminated {
                    return;
                }
            }
        }
    }

    /// 收集语句引用的单个资源
    fn scan_resource(&self, state: &mut ScanState, kind: ResourceKind, path: &str) {
        let path = path.trim();
        if path.is_empty() {
            return;
        }

        match kind {
            // 被调用的场景, 递归扫描
            ResourceKind::Scene => self.scan_scene(state, PathBuf::from("game/scene").join(path)),
            // 立绘, 扫描模型关联资产
            ResourceKind::Figure => self.scan_figure(state, path),
            // 其余资源直接打包
            ResourceKind::Animation
            | ResourceKind::Background
            | ResourceKind::Bgm
            | ResourceKind::Vocal
            | ResourceKind::Video => {
                let path = self.source.join("game").join(kind.to_string()).join(path);
                self.add_file(state, path);
            }
            // 配置与未知类型不应由语句产生
            ResourceKind::Config | ResourceKind::Other => {}
        }
    }

    /// 扫描立绘及其关联资源
    ///
    /// # Arguments
    /// * **relative** - 立绘文件相对于 `game/figure/` 目录的路径.
    ///
    /// # Behavior
    /// * 图片立绘仅打包图片本身.
    /// * Live2D 立绘打包模型, 纹理, 物理, 动作与表情等关联资产.
    /// * WMDL 立绘打包模型本身, 并递归扫描其引用的子模型.
    /// * Spine 与复合立绘 (Composite) 不受支持, 记录错误.
    fn scan_figure(&self, state: &mut ScanState, relative: &str) {
        // 立绘去重 (WMDL 的子模型可能引用同一个 Live2D 模型)
        if !state.figures.insert(relative.to_string()) || state.terminated {
            return;
        }

        let path = self.source.join("game").join("figure").join(relative);
        let content = match fs::read_to_string(&path) {
            Ok(content) => content,
            Err(error) if error.kind() == io::ErrorKind::NotFound => {
                self.push_scan_error(state, Error::new(path, ErrorKind::MissingResource));
                return;
            }
            Err(error) => {
                self.push_scan_error(state, Error::new(path, ErrorKind::Read(error)));
                return;
            }
        };
        self.add_file(state, path.clone());

        // 依据路径识别立绘类型
        match FigureKind::from_path(relative).0 {
            // 图片立绘, 已打包图片本身
            FigureKind::Image => {}
            // Live2D 立绘, 收集模型关联资产
            FigureKind::Live2d => self.scan_live2d_figure(state, &path, &content),
            // WMDL 立绘, 收集模型本身与子模型
            FigureKind::Wmdl => self.scan_wmdl_figure(state, relative, &content),
            // 不支持的立绘类型
            FigureKind::Spine => self.push_scan_error(
                state,
                Error::new(path, ErrorKind::UnsupportedFigure("Spine")),
            ),
            FigureKind::Composite => self.push_scan_error(
                state,
                Error::new(path, ErrorKind::UnsupportedFigure("Composite")),
            ),
        }
    }

    /// 扫描 Live2D 立绘的关联资产
    ///
    /// # Behavior
    /// * 模型 JSON 内部的资源路径相对于模型文件所在目录.
    fn scan_live2d_figure(&self, state: &mut ScanState, path: &Path, content: &str) {
        // 解析模型
        let model: Live2dModel = match content.parse() {
            Ok(model) => model,
            Err(error) => {
                self.push_scan_error(
                    state,
                    Error::new(path.to_path_buf(), ErrorKind::ParseFigure(error)),
                );
                return;
            }
        };

        // 模型文件所在目录
        let model_dir = path.parent().unwrap_or(Path::new(""));

        // 收集模型, 纹理, 物理, 动作与表情等关联资产
        for resource in model.resources().filter(|resource| !resource.is_empty()) {
            self.add_file(state, model_dir.join(resource));
            if state.terminated {
                return;
            }
        }
    }

    /// 扫描 WMDL 立绘的关联资源
    ///
    /// # Behavior
    /// * 主模型与子模型路径相对于 WMDL 文件所在目录.
    fn scan_wmdl_figure(&self, state: &mut ScanState, relative: &str, content: &str) {
        // 解析模型
        let model: WmdlModel = match content.parse() {
            Ok(model) => model,
            Err(error) => {
                let path = self.source.join("game").join("figure").join(relative);
                self.push_scan_error(state, Error::new(path, ErrorKind::ParseFigure(error)));
                return;
            }
        };

        // 主模型与子模型路径相对于 WMDL 文件所在目录
        let model_dir = parent_dir(relative);
        let resolve = |path: &str| {
            if model_dir.is_empty() {
                path.to_string()
            } else {
                format!("{model_dir}/{path}")
            }
        };

        // 主模型 (底模)
        if !model.model.is_empty() {
            self.scan_figure(state, &resolve(&model.model));
        }

        // 子模型
        for sub in &model.sub_models {
            if state.terminated {
                return;
            }
            if !sub.model.is_empty() {
                self.scan_figure(state, &resolve(&sub.model));
            }
        }
    }

    // -------- 打包 --------

    /// 执行打包, 将扫描到的文件写入压缩包
    ///
    /// # Returns
    /// (已打包文件数, 总体积, 压缩包体积).
    fn pack(&self, state: &mut ScanState) -> (usize, u64, u64) {
        // 打开输出文件 (已存在则覆盖)
        let file = match fs::File::create(&self.destination) {
            Ok(file) => file,
            Err(error) => {
                self.push_pack_error(
                    state,
                    Error::new(self.destination.clone(), ErrorKind::Io(error)),
                );
                state.terminated = true;
                return (0, 0, 0);
            }
        };

        // 按路径排序, 保证输出稳定
        let mut files: Vec<_> = state.files.iter().cloned().collect();
        files.sort();
        let count = files.len();
        let total_size = state.cumulative_size;

        // 汇报打包开始 (传入待打包文件列表)
        if let Some(reporter) = &self.progress_reporter {
            reporter.on_pack_start(&files, total_size);
        }

        // 压缩包写入器 (统计已写入的压缩字节)
        let mut writer = ZipWriter::new(CountingWriter::new(file));
        let options = SimpleFileOptions::default().compression_method(self.config.compression);

        // 已打包文件的原始体积
        let mut packed_size = 0u64;

        for (index, path) in files.iter().enumerate() {
            if state.terminated {
                break;
            }

            // 打开源文件
            let mut file = match fs::File::open(path) {
                Ok(file) => file,
                Err(error) => {
                    self.push_pack_error(state, Error::new(path.clone(), ErrorKind::Io(error)));
                    continue;
                }
            };
            let size = match file.metadata() {
                Ok(metadata) => metadata.len(),
                Err(error) => {
                    self.push_pack_error(state, Error::new(path.clone(), ErrorKind::Io(error)));
                    continue;
                }
            };

            // 以项目相对路径写入压缩包 (分隔符统一为 `/`)
            let name = path.strip_prefix(&self.source).unwrap_or(path);
            if let Err(error) = writer.start_file_from_path(name, options) {
                // 条目写入失败会破坏压缩包完整性, 终止打包
                self.push_pack_error(state, Error::new(path.clone(), ErrorKind::Zip(error)));
                state.terminated = true;
                break;
            }
            if let Err(error) = io::copy(&mut file, &mut writer) {
                // 条目写入失败会破坏压缩包完整性, 终止打包
                self.push_pack_error(state, Error::new(path.clone(), ErrorKind::Io(error)));
                state.terminated = true;
                break;
            }
            packed_size += size;

            // 汇报进度 (原始体积与累计压缩字节)
            if let Some(reporter) = &self.progress_reporter {
                let compressed = writer.get_ref().map_or(0, CountingWriter::written);
                reporter.on_pack_file(path, index + 1, packed_size, compressed);
            }
        }

        // 完成压缩包
        let file = match writer.finish() {
            Ok(file) => file,
            Err(error) => {
                self.push_pack_error(
                    state,
                    Error::new(self.destination.clone(), ErrorKind::Zip(error)),
                );
                state.terminated = true;
                return (count, total_size, 0);
            }
        };

        // 查询压缩包体积
        let final_size = match file.into_inner().metadata() {
            Ok(metadata) => metadata.len(),
            Err(error) => {
                self.push_pack_error(
                    state,
                    Error::new(self.destination.clone(), ErrorKind::Io(error)),
                );
                state.terminated = true;
                0
            }
        };

        if let Some(reporter) = &self.progress_reporter {
            reporter.on_pack_complete(final_size);
        }
        (count, total_size, final_size)
    }

    // -------- 工具 --------

    /// 记录扫描错误, 并询问汇报器是否中断
    fn push_scan_error(&self, state: &mut ScanState, error: Error) {
        state.terminated |= self
            .progress_reporter
            .as_ref()
            .is_some_and(|reporter| reporter.on_scan_error(&error));
        state.errors.push(error);
    }

    /// 记录打包错误, 并询问汇报器是否中断
    fn push_pack_error(&self, state: &mut ScanState, error: Error) {
        state.terminated |= self
            .progress_reporter
            .as_ref()
            .is_some_and(|reporter| reporter.on_pack_error(&error));
        state.errors.push(error);
    }

    /// 记录文件到打包列表
    ///
    /// # Behavior
    /// * 文件已记录时不做任何事 (去重).
    /// * 文件不存在或不是文件时记录错误.
    fn add_file(&self, state: &mut ScanState, path: PathBuf) {
        if state.files.contains(&path) {
            return;
        }

        // 检查文件存在且为普通文件
        if !path.is_file() {
            let detail = if path.is_dir() {
                ErrorKind::NotAFile
            } else {
                ErrorKind::MissingResource
            };
            self.push_scan_error(state, Error::new(path, detail));
            return;
        }

        // 获取文件体积
        let size = match path.metadata() {
            Ok(metadata) => metadata.len(),
            Err(error) => {
                self.push_scan_error(state, Error::new(path, ErrorKind::Read(error)));
                return;
            }
        };

        state.cumulative_size += size;
        state.files.insert(path.clone());

        // 汇报进度
        if let Some(reporter) = &self.progress_reporter {
            reporter.on_scan_file(&path, state.files.len(), state.cumulative_size);
        }
    }
}

// -------- 配置引用 --------

/// 配置中引用背景图的条目
const CONFIG_BACKGROUND_KEYS: &[&str] = &["Title_img", "Game_Logo"];

/// 配置中引用背景音乐的条目
const CONFIG_BGM_KEYS: &[&str] = &["Title_bgm"];

// -------- 工具 --------

/// 获取 `/` 分隔路径的父目录 (无父目录时返回空字符串)
fn parent_dir(path: &str) -> &str {
    path.rsplit_once('/')
        .map(|(parent, _)| parent)
        .unwrap_or("")
}

/// 统计写入字节数的写入器
///
/// 用于汇报压缩包写入进度 (`ZipWriter` 写入的即为压缩后的字节).
struct CountingWriter<W> {
    inner: W,
    written: u64,
}

impl<W> CountingWriter<W> {
    fn new(inner: W) -> Self {
        Self { inner, written: 0 }
    }

    /// 已写入的字节数
    fn written(&self) -> u64 {
        self.written
    }

    /// 解包, 返回内部写入器
    fn into_inner(self) -> W {
        self.inner
    }
}

impl<W: io::Write> io::Write for CountingWriter<W> {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        let written = self.inner.write(buf)?;
        self.written += written as u64;
        Ok(written)
    }

    fn flush(&mut self) -> io::Result<()> {
        self.inner.flush()
    }
}

impl<W: io::Seek> io::Seek for CountingWriter<W> {
    fn seek(&mut self, pos: io::SeekFrom) -> io::Result<u64> {
        self.inner.seek(pos)
    }
}

#[cfg(test)]
mod tests {
    use std::io::Write;

    use super::*;

    #[test]
    fn parent_dir_basic() {
        assert_eq!(parent_dir("model1/model.json"), "model1");
        assert_eq!(parent_dir("sub/dir/model.wmdl"), "sub/dir");
        assert_eq!(parent_dir("model.json"), "");
        assert_eq!(parent_dir(""), "");
    }

    #[test]
    fn counting_writer_counts_bytes() {
        let mut writer = CountingWriter::new(io::Cursor::new(Vec::new()));
        writer.write_all(b"hello").unwrap();
        writer.write_all(b" world").unwrap();
        assert_eq!(writer.written(), 11);
        assert_eq!(writer.into_inner().into_inner().len(), 11);
    }
}
